package io.github.miklires.mauction;import org.bukkit.*;import org.bukkit.inventory.*;import java.util.*;public final class AuctionMenu implements InventoryHolder{private final List<Listing>listings;private final Inventory inventory;public AuctionMenu(String title,List<Listing>listings,Messages messages){this.listings=List.copyOf(listings);inventory=Bukkit.createInventory(this,54,title);for(int i=0;i<Math.min(45,listings.size());i++){Listing listing=listings.get(i);ItemStack item=ItemCodec.decode(listing.item());var meta=item.getItemMeta();List<net.kyori.adventure.text.Component>lore=new ArrayList<>(Optional.ofNullable(meta.lore()).orElse(List.of()));lore.add(net.kyori.adventure.text.Component.text(messages.text("lore-price","price",listing.price())));lore.add(net.kyori.adventure.text.Component.text(messages.text("lore-seller","seller",listing.sellerName())));lore.add(net.kyori.adventure.text.Component.text(messages.text("lore-id","id",listing.id())));meta.lore(lore);item.setItemMeta(meta);inventory.setItem(i,item);}}public Optional<Listing>listing(int slot){return slot>=0&&slot<listings.size()?Optional.of(listings.get(slot)):Optional.empty();}@Override public Inventory getInventory(){return inventory;}}
